        "code": "from typing import Literal\nfrom pydantic import BaseModel, Field\nfrom crewai import Agent, Crew, Process, Task\nfrom crewai.flow.flow import Flow, listen, router, start\n\nclass LeadAuditReport(BaseModel):\n    fit_score: int = Field(ge=0, le=100, description=\"Điểm phù hợp 0-100\")\n    recommended_tier: Literal[\"Starter\", \"Growth\", \"Enterprise\"]\n    pain_points: list[str] = Field(max_length=4)\n    zalo_summary: str = Field(description=\"Tóm tắt <= 3 câu đẩy qua ZaloBot cho Sale\")\n\nclass LeadFlowState(BaseModel):\n    lead_id: str = \"\"\n    company_size: int = 0\n    raw_note: str = \"\"\n    report: LeadAuditReport | None = None\n\nclass LeadQualificationFlow(Flow[LeadFlowState]):\n    @start()\n    def sanitize_and_score_rules(self) -> None:\n        # Tiền xử lý thuần Python: 0 token, < 5ms\n        self.state.raw_note = self.state.raw_note.strip()\n\n    @router(sanitize_and_score_rules)\n    def route_by_potential(self) -> Literal[\"fast_track\", \"deep_crew\"]:\n        # Chặn vòng lặp đốt token cho Lead quá nhỏ hoặc thiếu ngữ cảnh\n        if self.state.company_size < 15 or len(self.state.raw_note) < 25:\n            return \"fast_track\"\n        return \"deep_crew\"\n\n    @listen(\"fast_track\")\n    def handle_fast_track(self) -> LeadAuditReport:\n        report = LeadAuditReport(\n            fit_score=35,\n            recommended_tier=\"Starter\",\n            pain_points=[\"Thiếu mô tả quy mô sâu, cần Sale gọi xác minh bước 1\"],\n            zalo_summary=f\"Lead #{self.state.lead_id} ({self.state.company_size} NS): phân bổ nhánh Starter nhanh.\",\n        )\n        self.state.report = report\n        return report\n\n    @listen(\"deep_crew\")\n    def run_enterprise_crew(self) -> LeadAuditReport:\n        analyst = Agent(\n            role=\"Solution Architect B2B\",\n            goal=\"Phân tích nỗi đau vận hành và đề xuất gói ERP/CRM phù hợp\",\n            backstory=\"Chuyên gia khảo sát kiến trúc hệ thống doanh nghiệp Việt Nam.\",\n            max_iter=3,\n            max_execution_time=20,\n            allow_delegation=False,\n        )\n        triage_task = Task(\n            description=(\n                f\"Phân tích Lead #{self.state.lead_id}, quy mô {self.state.company_size} nhân sự. \"\n                f\"Nhu cầu ghi nhận: {self.state.raw_note}\"\n            ),\n            expected_output=\"Báo cáo chuẩn cấu trúc LeadAuditReport.\",\n            agent=analyst,\n            output_pydantic=LeadAuditReport,\n        )\n        crew = Crew(agents=[analyst], tasks=[triage_task], process=Process.sequential)\n        crew.kickoff()\n        self.state.report = triage_task.output.pydantic\n        return self.state.report\n\nif __name__ == \"__main__\":\n    flow = LeadQualificationFlow()\n    outcome = flow.kickoff(inputs={\"lead_id\": \"LD-2026-881\", \"company_size\": 85, \"raw_note\": \"Cần đồng bộ 4 chi nhánh POS, CRM chia số ZaloBot và xuất hóa đơn MISA tự động.\"})\n    print(outcome.model_dump_json(indent=2))"
