        "code": "import asyncio\nfrom pathlib import Path\nfrom autogen_agentchat.agents import AssistantAgent, CodeExecutorAgent\nfrom autogen_agentchat.conditions import MaxMessageTermination, TextMentionTermination\nfrom autogen_agentchat.teams import RoundRobinGroupChat\nfrom autogen_ext.code_executors.docker import DockerCommandLineCodeExecutor\nfrom autogen_ext.models.openai import OpenAIChatCompletionClient\n\nasync def run_isolated_bi_audit() -> None:\n    # Cô lập thư mục làm việc tạm cho sandbox Docker, tuyệt đối không mount repo gốc hay .env\n    sandbox_dir = Path(\"./tmp_bi_sandbox\")\n    sandbox_dir.mkdir(parents=True, exist_ok=True)\n\n    model_client = OpenAIChatCompletionClient(model=\"gpt-4o-mini\")\n\n    # Di sản giá trị nhất: ép mã Python do AI viết chạy trong container python:3-slim cô lập\n    async with DockerCommandLineCodeExecutor(\n        image=\"python:3.12-slim\",\n        work_dir=sandbox_dir,\n        timeout=30,\n    ) as docker_executor:\n        analyst = AssistantAgent(\n            name=\"bi_analyst\",\n            model_client=model_client,\n            system_message=(\n                \"Viết mã Python gọn để tính tổng hợp số liệu từ file CSV trong thư mục làm việc. \"\n                \"Khi executor chạy ra kết quả sạch, kết luận ngắn gọn và ghi TERMINATE.\"\n            ),\n        )\n        executor_agent = CodeExecutorAgent(name=\"sandbox_runner\", code_executor=docker_executor)\n\n        # Chốt chặn sống còn ngăn GroupChat lặp vô tận khi code lỗi liên tiếp\n        stop_condition = TextMentionTermination(\"TERMINATE\") | MaxMessageTermination(max_messages=6)\n\n        team = RoundRobinGroupChat(\n            participants=[analyst, executor_agent],\n            termination_condition=stop_condition,\n        )\n        result = await team.run(task=\"Tính tổng doanh thu theo kênh từ metrics.csv và in bảng tóm tắt.\")\n        for msg in result.messages:\n            print(f\"[{msg.source}] {str(msg.content)[:240]}\")\n\nif __name__ == \"__main__\":\n    asyncio.run(run_isolated_bi_audit())"
