        "code": "import fs from \"node:fs\";\nimport path from \"node:path\";\nimport dns from \"node:dns/promises\";\nimport net from \"node:net\";\n\nconst ALLOWED_ROOTS = [\"/srv/domation/public-docs\", \"/srv/domation/templates\"].map((p) =>\n  fs.realpathSync(p)\n);\nconst ALLOWED_EGRESS_HOSTS = new Set([\"api.domation.net\", \"docs.nextjs.org\"]);\n\nexport function assertSafeFilePath(requestedPath: string): string {\n  const resolvedReal = fs.realpathSync(path.resolve(requestedPath));\n  const baseName = path.basename(resolvedReal);\n  if (baseName.startsWith(\".env\") || resolvedReal.includes(\"/.git/\")) {\n    throw new Error(\"BLOCKED_SENSITIVE_FILE: Từ chối đọc tệp cấu hình hoặc khóa bí mật.\");\n  }\n  const isInsideRoot = ALLOWED_ROOTS.some(\n    (root) => resolvedReal === root || resolvedReal.startsWith(root + path.sep)\n  );\n  if (!isInsideRoot) {\n    throw new Error(\"PATH_ALLOWLIST_VIOLATION: Đường dẫn vượt ra ngoài vùng cấp phép.\");\n  }\n  return resolvedReal;\n}\n\nfunction isPrivateOrMetadataIp(ip: string): boolean {\n  if (net.isIPv4(ip)) {\n    const [a, b] = ip.split(\".\").map(Number);\n    if (a === 10 || a === 127 || a === 0) return true;\n    if (a === 169 && b === 254) return true; // AWS/GCP Metadata endpoint\n    if (a === 172 && b >= 16 && b <= 31) return true;\n    if (a === 192 && b === 168) return true;\n  }\n  return ip === \"::1\" || ip.startsWith(\"fe80:\") || ip.startsWith(\"fc\") || ip.startsWith(\"fd\");\n}\n\nexport async function assertSafeOutboundUrl(rawUrl: string): Promise<URL> {\n  const parsed = new URL(rawUrl);\n  if (parsed.protocol !== \"https:\") {\n    throw new Error(\"EGRESS_BLOCKED: Chỉ cho phép giao thức HTTPS đã mã hóa.\");\n  }\n  if (!ALLOWED_EGRESS_HOSTS.has(parsed.hostname)) {\n    throw new Error(`DOMAIN_NOT_ALLOWLISTED: Domain ${parsed.hostname} chưa được cấp phép.`);\n  }\n  const records = await dns.lookup(parsed.hostname, { all: true });\n  for (const rec of records) {\n    if (isPrivateOrMetadataIp(rec.address)) {\n      throw new Error(\"SSRF_DETECTED: Tên miền phân giải vào dải IP nội bộ hoặc metadata.\");\n    }\n  }\n  return parsed;\n}"
