        "code": "import { createPiece, createAction, PieceAuth, Property } from \"@activepieces/pieces-framework\";\nimport { httpClient, HttpMethod } from \"@activepieces/pieces-common\";\n\nexport const zaloOaAuth = PieceAuth.SecretText({\n  displayName: \"Zalo OA Access Token\",\n  description: \"Token nội bộ quản lý qua Vault để gửi tin ZNS xác nhận đơn hoặc lịch hẹn.\",\n  required: true,\n});\n\nexport const sendZaloZnsNotice = createAction({\n  name: \"send_zalo_zns_notice\",\n  auth: zaloOaAuth,\n  displayName: \"Gửi Tin Zalo ZNS Theo Template\",\n  description: \"Kích hoạt gửi thông báo giao dịch ZNS và trả về message_id đối soát CRM.\",\n  props: {\n    phoneE164: Property.ShortText({\n      displayName: \"Số điện thoại khách hàng (84...)\",\n      required: true,\n    }),\n    templateId: Property.ShortText({\n      displayName: \"Mã Template ZNS đã duyệt\",\n      required: true,\n    }),\n    orderCode: Property.ShortText({\n      displayName: \"Mã đơn hàng / Mã phiếu MISA\",\n      required: true,\n    }),\n  },\n  async run(context) {\n    const { phoneE164, templateId, orderCode } = context.propsValue;\n    const res = await httpClient.sendRequest({\n      method: HttpMethod.POST,\n      url: \"https://business.openapi.zalo.me/message/template\",\n      headers: { access_token: context.auth },\n      body: {\n        phone: phoneE164,\n        template_id: templateId,\n        template_data: { order_code: orderCode },\n        tracking_id: `dom-${orderCode}-${Date.now()}`,\n      },\n    });\n    return { ok: res.status === 200, data: res.body };\n  },\n});\n\nexport const domationZaloZnsPiece = createPiece({\n  displayName: \"DOMATION Zalo ZNS\",\n  auth: zaloOaAuth,\n  minimumSupportedRelease: \"0.30.0\",\n  logoUrl: \"https://domation.net/favicon.ico\",\n  authors: [\"TurnioDEV\"],\n  actions: [sendZaloZnsNotice],\n  triggers: [],\n});"
